            throw new IllegalArgumentException("userId must not be null or empty");
        }

        UserProfile user = userStore.get(userId);
        if (user == null) {
            logger.error("User not found for userId: {}", userId);
            throw new IllegalStateException("User not found for userId: " + userId);
        }

        // Log the user being processed at INFO level
        logger.info("Processing user profile for userId: {}, username: {}", user.getUserId(), user.getUsername());

        // Additional processing logic can be added here
        // For now, we simulate processing by logging success
        logger.debug("User profile processed successfully for userId: {}", userId);
    }
}
